64	
65	@RestController
66	@CrossOrigin(exposedHeaders = "errors, content-type")
67	@RequestMapping("/api")
68	public class OwnerRestControllerV1 implements OwnersApi {
69	
70	    /** Dedicated audit logger; emits one line per successful owner create. */
71	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
72	
73	    private final ClinicService clinicService;
74	
75	    private final OwnerMapper ownerMapper;
76	
77	    private final PetMapper petMapper;
78	
79	    private final VisitMapper visitMapper;
80	
81	    public OwnerRestControllerV1(ClinicService clinicService,
82	                                 OwnerMapper ownerMapper,
83	                                 PetMapper petMapper,
84	                                 VisitMapper visitMapper) {
85	        this.clinicService = clinicService;
86	        this.ownerMapper = ownerMapper;
87	        this.petMapper = petMapper;
88	        this.visitMapper = visitMapper;
89	    }
90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
94	        Collection<Owner> owners;
95	        if (lastName != null) {
96	            owners = this.clinicService.findOwnerByLastName(lastName);
97	        } else {
98	            owners = this.clinicService.findAllOwners();
99	        }
100	        if (owners.isEmpty()) {
101	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
102	        }
103	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
104	    }
105	
106	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
107	    @Override
108	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
109	        Owner owner = this.clinicService.findOwnerById(ownerId);
110	        if (owner == null) {
111	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
112	        }
113	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
119	        // Normalize the address up front so every downstream use (the required-field check,
120	        // household-duplicate detection, the shared household id and the stored/returned value)
121	        // works from the same canonical form.
122	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
123	        List<String> missingFields = new ArrayList<>();
124	        if (isBlank(ownerFieldsDto.getFirstName())) {
125	            missingFields.add("firstName");
126	        }
127	        if (isBlank(ownerFieldsDto.getLastName())) {
128	            missingFields.add("lastName");
129	        }
130	        // Reject an address that is blank once normalized (e.g. whitespace-only input).
131	        if (isBlank(normalizedAddress)) {
132	            missingFields.add("address");
133	        }
134	        if (isBlank(ownerFieldsDto.getCity())) {
135	            missingFields.add("city");
136	        }
137	        if (isBlank(ownerFieldsDto.getTelephone())) {
138	            missingFields.add("telephone");
139	        }
140	        if (!missingFields.isEmpty()) {
141	            throw new InvalidOwnerFieldsException(missingFields);
142	        }
143	        // Determine the effective registration date up front so every downstream use (the daily
144	        // create-limit, the stored value and anything derived from it such as the membership number's
145	        // year segment) works from the same business-day-adjusted date. The effective date is the
146	        // supplied value when present, otherwise the server's current date; a weekend date is rolled
147	        // forward to the following Monday.
148	        LocalDate effectiveRegistrationDate = ownerFieldsDto.getRegistrationDate() != null
149	            ? ownerFieldsDto.getRegistrationDate()
150	            : LocalDate.now();
151	        effectiveRegistrationDate = toBusinessDay(effectiveRegistrationDate);
152	        // Reject the request once the day's owner-creation limit is reached: when 100 or more owners
153	        // already carry this adjusted business day's registration date, no further owners may be
154	        // created for that day.
155	        int ownersRegisteredToday = countOwnersRegisteredOn(effectiveRegistrationDate);
156	        if (ownersRegisteredToday >= MAX_OWNERS_PER_DAY) {
157	            throw new DailyOwnerLimitExceededException(effectiveRegistrationDate);
158	        }
159	        // Flag a bulk signup once more than 80 owners have already been created for this
160	        // business day, sharing the same daily accumulation path as the create-limit rule above.
161	        boolean bulkSignupWarning = ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD;
162	        // Reject the request when the owner's city is already full: a city that already holds the
163	        // maximum of 50 owners (compared case-insensitively, as elsewhere) accepts no more.
164	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= MAX_OWNERS_PER_CITY) {
165	            throw new CityAtCapacityException(ownerFieldsDto.getCity());
166	        }
167	        // Normalize the telephone into E.164 form; a number that cannot form a valid
168	        // E.164 value is rejected with a 400.
169	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
170	        // Email is optional; when present it must be a syntactically valid address and is
171	        // stored lower-cased. An invalid address is rejected with a 400.
172	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
173	        // Reject the request if the E.164 telephone is already used by any other owner.
174	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
175	            .map(Owner::getTelephone)
176	            .filter(existing -> existing != null)
177	            .anyMatch(normalizedTelephone::equals);
178	        if (telephoneInUse) {
179	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
180	        }
181	        // Household handling for a matching last name + address (compared case-insensitively with
182	        // collapsed whitespace). By default such a request is rejected as a duplicate household;
183	        // when the caller opts in via 'sharesHousehold' the owner is instead admitted into the shared
184	        // household and every member (the new owner and any existing ones) is stamped with the same
185	        // stable 'householdId'.
186	        String normalizedLastName = collapse(ownerFieldsDto.getLastName());
187	        String householdId = null;
188	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
189	            householdId = householdId(normalizedLastName, normalizedAddress);
190	            // Backfill the shared identifier onto any existing member of this household so the whole
191	            // household carries the same stable value.
192	            for (Owner existing : this.clinicService.findAllOwners()) {
193	                if (collapse(existing.getLastName()).equals(normalizedLastName)
194	                    && normalizeAddress(existing.getAddress()).equals(normalizedAddress)
195	                    && !householdId.equals(existing.getHouseholdId())) {
196	                    existing.setHouseholdId(householdId);
197	                    this.clinicService.saveOwner(existing);
198	                }
199	            }
200	        } else {
201	            boolean householdInUse = this.clinicService.findAllOwners().stream()
202	                .anyMatch(existing -> collapse(existing.getLastName()).equals(normalizedLastName)
203	                    && normalizeAddress(existing.getAddress()).equals(normalizedAddress));
204	            if (householdInUse) {
205	                throw new DuplicateOwnerHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
206	            }
207	        }
208	        HttpHeaders headers = new HttpHeaders();
209	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
210	        owner.setAddress(normalizedAddress);
211	        owner.setTelephone(normalizedTelephone);
212	        owner.setEmail(normalizedEmail);
213	        owner.setHouseholdId(householdId);
214	        // Record how many existing owners (before this create) share this owner's first and last
215	        // name, compared case-insensitively. Computed against the current owners so the new owner
216	        // itself is never counted.
217	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
218	        // Record the size of this owner's household (owners sharing the same householdId) after this
219	        // create: the existing members already stamped with the shared identifier plus this new
220	        // owner. An owner not admitted into any household is a household of one.
221	        owner.setHouseholdSize(countHouseholdMembers(householdId) + 1);
222	        // Persist the bulk-signup flag computed above so it is returned on subsequent reads.
223	        owner.setBulkSignupWarning(bulkSignupWarning);
224	        // Store the business-day-adjusted effective registration date computed above. This defaults
225	        // to the server's current date when none was supplied and rolls any weekend date forward to
226	        // the following Monday, so everything derived from it (e.g. the membership number's year
227	        // segment) uses the adjusted date.
228	        owner.setRegistrationDate(effectiveRegistrationDate);
229	        // Assign the customer code: '<CITY3>-<LAST3>-<NNNN>' where CITY3 is the upper-cased first
230	        // three letters of the city, LAST3 the upper-cased first three letters of the last name and
231	        // NNNN is a per-city 4-digit zero-padded sequence equal to one more than the number of
232	        // owners already in that city.
233	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
234	        this.clinicService.saveOwner(owner);
235	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
236	        // Emit an audit trail line for the successful create, carrying the owner id, the assigned
237	        // customer code, the effective registration date and the numeric membership level.
238	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
239	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), ownerDto.getMembershipLevel());
240	        headers.setLocation(UriComponentsBuilder.newInstance()
241	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
242	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
243	    }
244	
245	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
246	    @Override
247	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
248	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
249	        if (currentOwner == null) {
250	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
251	        }
252	        currentOwner.setAddress(ownerFieldsDto.getAddress());
253	        currentOwner.setCity(ownerFieldsDto.getCity());
254	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
255	        currentOwner.setLastName(ownerFieldsDto.getLastName());
256	        currentOwner.setTelephone(toE164(ownerFieldsDto.getTelephone()));
257	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
258	        this.clinicService.saveOwner(currentOwner);
259	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
260	    }
261	
262	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
263	    @Transactional
264	    @Override
265	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
266	        Owner owner = this.clinicService.findOwnerById(ownerId);
267	        if (owner == null) {
268	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
269	        }
270	        this.clinicService.deleteOwner(owner);
271	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
272	    }
