293	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
294	    @Override
295	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
296	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
