326	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
327	    @Override
328	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
329	        Owner owner = this.clinicService.findOwnerById(ownerId);
330	        if (owner != null) {
331	            Pet pet = owner.getPet(petId);
332	            if (pet != null) {
333	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
334	            }
335	        }
336	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
