338	
339	    private static boolean isBlank(String value) {
340	        return value == null || value.trim().isEmpty();
341	    }
342	
343	    /**
344	     * Normalize an owner identity field for household-duplicate comparison: trim, collapse every
345	     * run of whitespace to a single space, and lower-case. Used so that last name and address are
346	     * compared case-insensitively with collapsed whitespace.
347	     */
348	    private static String collapse(String value) {
349	        if (value == null) {
350	            return "";
351	        }
352	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
353	    }
354	
355	    /**
356	     * Common street-type abbreviations expanded during address normalization.
357	     */
358	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
359	        "ST", "STREET",
360	        "RD", "ROAD",
361	        "AVE", "AVENUE");
362	
363	    /**
364	     * Normalize an owner address into its canonical stored/compared form: trim, collapse every run
365	     * of whitespace to a single space, upper-case, and expand common street-type abbreviations
366	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). Returns an empty string for
367	     * a {@code null} or blank input. The transformation is idempotent, so an already-normalized
368	     * address maps to itself.
369	     */
370	    private static String normalizeAddress(String value) {
371	        if (value == null) {
372	            return "";
373	        }
374	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
375	        if (collapsed.isEmpty()) {
376	            return "";
377	        }
378	        String[] tokens = collapsed.split(" ");
379	        StringBuilder sb = new StringBuilder(collapsed.length());
380	        for (int i = 0; i < tokens.length; i++) {
381	            if (i > 0) {
382	                sb.append(' ');
383	            }
384	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
385	        }
386	        return sb.toString();
387	    }
388	
389	    /**
390	     * Derive the stable household identifier shared by owners with the same normalized last name
391	     * and address. It is a deterministic function of those two values, so every member of a
392	     * household independently derives the same identifier: the first 12 upper-case hex characters
393	     * of {@code SHA-256(normalizedLastName + '\n' + normalizedAddress)}.
394	     */
395	    private static String householdId(String normalizedLastName, String normalizedAddress) {
396	        try {
397	            byte[] digest = MessageDigest.getInstance("SHA-256")
398	                .digest((normalizedLastName + "\n" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
399	            StringBuilder sb = new StringBuilder(digest.length * 2);
400	            for (byte b : digest) {
401	                sb.append(String.format("%02x", b));
402	            }
403	            return sb.substring(0, 12).toUpperCase();
404	        }
405	        catch (NoSuchAlgorithmException e) {
406	            throw new IllegalStateException("SHA-256 not available", e);
407	        }
408	    }
409	
410	    /**
411	     * Build the customer code for a new owner: {@code '<CITY3>-<LAST3>-<NNNN>'} where CITY3 is the
412	     * upper-cased first three letters of the city, LAST3 the upper-cased first three letters of the
413	     * last name and NNNN is a per-city 4-digit zero-padded sequence equal to one more than the
414	     * number of owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
415	     */
416	    /**
417	     * Count the existing owners that share the given first and last name, compared
418	     * case-insensitively. Called before the new owner is saved, so the returned value reflects the
419	     * namesakes that already existed at creation time (the new owner itself is not included).
420	     */
421	    private int countNamesakes(String firstName, String lastName) {
422	        return (int) this.clinicService.findAllOwners().stream()
423	            .filter(existing -> existing.getFirstName() != null && existing.getLastName() != null)
424	            .filter(existing -> existing.getFirstName().equalsIgnoreCase(firstName)
425	                && existing.getLastName().equalsIgnoreCase(lastName))
426	            .count();
427	    }
428	
429	    /**
430	     * Count the existing owners that already belong to the given household (i.e. carry the same
431	     * non-null householdId). Called after any existing members have been backfilled with the shared
432	     * identifier but before the new owner is saved, so the returned value reflects the members that
433	     * already existed at creation time (the new owner itself is not included). Returns 0 when the
434	     * new owner is not part of any household ({@code householdId} is null).
435	     */
436	    private int countHouseholdMembers(String householdId) {
437	        if (householdId == null) {
438	            return 0;
439	        }
440	        return (int) this.clinicService.findAllOwners().stream()
441	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
442	            .count();
443	    }
444	
445	    /**
446	     * The maximum number of owners a single city may contain. Once a city holds this many owners a
447	     * request to create another owner in it is rejected as a conflict.
448	     */
449	    private static final int MAX_OWNERS_PER_CITY = 50;
450	
451	    /**
452	     * Count the existing owners registered in the given city, compared case-insensitively (as in
453	     * {@link #nextCustomerCode}). Called before the new owner is saved, so the returned value
454	     * reflects the owners that already existed at creation time.
455	     */
456	    private int countOwnersInCity(String city) {
457	        return (int) this.clinicService.findAllOwners().stream()
458	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
459	            .count();
460	    }
461	
462	    /**
463	     * The maximum number of owners that may be created on a single day. Once this many owners
464	     * already carry a given day's registration date, a request to create another owner that day is
465	     * rejected with a 429.
466	     */
467	    private static final int MAX_OWNERS_PER_DAY = 100;
468	
469	    /**
470	     * The number of owners that may be created on a single day before the bulk-signup warning is
471	     * flagged. Once more than this many owners already carry a given day's registration date, a
472	     * newly created owner is flagged with {@code bulkSignupWarning} set true.
473	     */
474	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
475	
476	    /**
477	     * Count the existing owners whose registration date is the given day. Called before the new
478	     * owner is saved, so the returned value reflects the owners that already existed at creation
479	     * time.
480	     */
481	    private int countOwnersRegisteredOn(LocalDate date) {
482	        return (int) this.clinicService.findAllOwners().stream()
483	            .filter(existing -> date.equals(existing.getRegistrationDate()))
484	            .count();
485	    }
486	
487	    /**
488	     * Roll a date forward onto a business day: a Saturday or Sunday is advanced to the following
489	     * Monday, while a weekday is returned unchanged. Used so the effective registration date (whether
490	     * supplied or defaulted) always falls on a business day.
491	     */
492	    private static LocalDate toBusinessDay(LocalDate date) {
493	        return switch (date.getDayOfWeek()) {
494	            case SATURDAY -> date.plusDays(2);
495	            case SUNDAY -> date.plusDays(1);
496	            default -> date;
497	        };
498	    }
499	
500	    private String nextCustomerCode(String city, String lastName) {
501	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
502	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
503	        long sequence = this.clinicService.findAllOwners().stream()
504	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
505	            .count() + 1L;
506	        return String.format("%s-%s-%04d", city3, last3, sequence);
507	    }
508	
509	    /**
510	     * Convert a raw telephone into E.164 form. Spaces, dashes and brackets are stripped. A leading
511	     * {@code '+'} with its country code is preserved; otherwise the Australian country code
512	     * {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the national digits.
513	     * The result must be a {@code '+'} followed by 8 to 15 digits, otherwise an
514	     * {@link InvalidOwnerFieldsException} is thrown so the request is rejected with a 400.
515	     */
516	    private static String toE164(String raw) {
517	        String cleaned = raw.trim().replaceAll("[\\s()\\-]", "");
518	        boolean hasCountryCode = cleaned.startsWith("+");
519	        String digits = hasCountryCode ? cleaned.substring(1) : cleaned;
520	        if (!digits.matches("\\d+")) {
521	            throw new InvalidOwnerFieldsException(List.of("telephone"));
522	        }
523	        if (!hasCountryCode) {
524	            if (digits.startsWith("0")) {
525	                digits = digits.substring(1);
526	            }
527	            digits = "61" + digits;
528	        }
529	        if (digits.length() < 8 || digits.length() > 15) {
530	            throw new InvalidOwnerFieldsException(List.of("telephone"));
531	        }
532	        return "+" + digits;
533	    }
534	
535	    /**
536	     * Pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
537	     * and a domain with at least one dot-separated label, none of which contain whitespace or
538	     * a second {@code @}. This is deliberately permissive but rejects obviously malformed input.
539	     */
540	    private static final Pattern EMAIL_PATTERN =
541	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
542	
543	    /**
544	     * Validate and normalize an optional owner email. Returns {@code null} when no email was
545	     * supplied (the field is optional). When supplied it must be a syntactically valid address,
546	     * otherwise an {@link InvalidOwnerFieldsException} is thrown so the request is rejected with a
547	     * 400. A valid address is returned lower-cased.
548	     */
549	    private static String normalizeEmail(String email) {
550	        if (email == null || email.isEmpty()) {
551	            return null;
552	        }
553	        String trimmed = email.trim();
554	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
555	            throw new InvalidOwnerFieldsException(List.of("email"));
556	        }
557	        return trimmed.toLowerCase();
558	    }
559	}
